'use strict';
(()=>{
 const $=id=>document.getElementById(id),A=GeoRadarAnalysisModel;let active=false,last;
 const section=document.createElement('section');section.className='analysis-controls';section.innerHTML='<div class="divider"></div><h3>Art der Auswertung</h3><p class="micro">Nur nach ausdrücklicher Auswahl. Grundlage sind die geladenen, aktuell gefilterten Firmen.</p><div id="analysis-types"></div><button id="analysis-start" class="outline" disabled>Auswertung starten</button><p id="analysis-state" class="micro" role="status">Noch keine Auswertung gestartet.</p><div id="analysis-actions" hidden><button id="analysis-dashboard" class="outline">Management-Dashboard öffnen</button><button id="analysis-summary" class="subtle">Zusammenfassung herunterladen</button></div><div class="divider"></div><h3>Gefilterte Ergebnisse exportieren</h3><div class="output-actions"><button id="analysis-csv" class="subtle">CSV herunterladen</button><button id="analysis-xlsx" class="subtle">Excel herunterladen</button></div>';
 document.querySelector('.territory-controls').after(section);
 for(const t of A.types){const label=document.createElement('label'),check=document.createElement('input'),text=document.createElement('span');check.type='checkbox';check.value=t.id;check.disabled=!t.available;check.dataset.analysis=t.id;text.textContent=t.label;if(!t.available){const note=document.createElement('small');note.textContent='Noch nicht verfügbar: '+t.reason;text.append(note);}label.append(check,text);$('analysis-types').append(label);check.onchange=()=>{$('analysis-start').disabled=!selection().length;$('analysis-state').textContent='Auswahl geändert. Auswertung starten, um sie anzuwenden.';};}
 const dialog=document.createElement('dialog');dialog.id='analysis-dialog';dialog.innerHTML='<div class="dialog-top"><h2>Management-Dashboard</h2><button id="analysis-close" class="icon-button" aria-label="Dashboard schließen">×</button></div><p id="dashboard-basis" class="micro"></p><div id="dashboard-results"></div>';document.body.append(dialog);$('analysis-close').onclick=()=>dialog.close();
 function selection(){return [...document.querySelectorAll('[data-analysis]:checked')].map(c=>c.value);}
 function download(name,body,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([body],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function table(title,rows){const block=document.createElement('section'),h=document.createElement('h3'),table=document.createElement('table');h.textContent=title;const head=document.createElement('tr');for(const text of ['Merkmal','Anzahl']){const th=document.createElement('th');th.scope='col';th.textContent=text;head.append(th);}table.append(head);for(const [key,count] of rows){const row=document.createElement('tr'),a=document.createElement('td'),b=document.createElement('td');a.textContent=key;b.textContent=count;row.append(a,b);table.append(row);}block.append(h,table);return block;}
 function run(ids=selection()){
  if(!ids.length){active=false;$('analysis-actions').hidden=true;$('analysis-state').textContent='Keine Auswertung ausgewählt.';return;}
  last=A.aggregate(GeoRadarCompanies.getFilteredRecords(),ids,GeoRadarTerritories.getConfiguration());active=true;$('analysis-actions').hidden=false;$('analysis-state').textContent=last.total+' Unternehmen ausgewertet · '+new Date(last.generatedAt).toLocaleTimeString('de-DE');
  $('dashboard-basis').textContent=last.total+' Unternehmen · geladener Datenstand, aktueller Filter · keine Gesamtmarkt-Hochrechnung';const out=$('dashboard-results');out.replaceChildren();
  if(last.distribution){out.append(table('Kunden- und Leadverteilung',last.distribution.status),table('Länder',last.distribution.countries));}
  if(last.representatives){out.append(table('Vertreter',[...last.representatives.counts,['Nicht zugeordnet',last.representatives.unassigned]]));const note=document.createElement('p');note.textContent=last.representatives.note;out.append(note);}
  if(last.industries){out.append(table('Branchen',last.industries.industries),table('Orte',last.industries.locations),table('Standortqualität',[['Mit Koordinaten',last.industries.withCoordinates],['Nur PLZ-Präfix',last.industries.prefixOnly],['Ohne Kartenposition',last.industries.withoutPosition]]));}
  document.dispatchEvent(new CustomEvent('georadar:analysis-updated',{detail:last}));
 }
 $('analysis-start').onclick=()=>{run();if(active)dialog.showModal();};$('analysis-dashboard').onclick=()=>dialog.showModal();$('analysis-summary').onclick=()=>{if(last)download('GeoRadar-Zusammenfassung.txt',A.summary(last),'text/plain;charset=utf-8');};
 function exportRecords(format){const records=GeoRadarCompanies.getFilteredRecords();if(!records.length)return;if(format==='csv')download('GeoRadar-Ergebnisse.csv',A.csv(records),'text/csv;charset=utf-8');else{const rows=[A.exportColumns,...records.map(r=>A.exportColumns.map(k=>{const v=r[k];return typeof v==='string'&&/^[\s]*[=+@-]/.test(v)?"'"+v:v??'';}))],sheet=XLSX.utils.aoa_to_sheet(rows),book=XLSX.utils.book_new();XLSX.utils.book_append_sheet(book,sheet,'Ergebnisse');download('GeoRadar-Ergebnisse.xlsx',XLSX.write(book,{type:'array',bookType:'xlsx'}),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');}}
 $('analysis-csv').onclick=()=>exportRecords('csv');$('analysis-xlsx').onclick=()=>exportRecords('xlsx');
 function update(){const none=!GeoRadarCompanies.getFilteredRecords().length;$('analysis-csv').disabled=none;$('analysis-xlsx').disabled=none;if(active&&last)run(last.analyses);}
 document.addEventListener('georadar:filter-updated',update);
 window.GeoRadarAnalysis={selection,run,isActive:()=>active,getResult:()=>last,setSelection:(ids,execute=false)=>{for(const c of document.querySelectorAll('[data-analysis]'))c.checked=!c.disabled&&ids.includes(c.value);$('analysis-start').disabled=!selection().length;if(execute)run();else{active=false;last=undefined;$('analysis-actions').hidden=true;$('analysis-state').textContent='Noch keine Auswertung gestartet.';}}};update();
})();
